def longest_common_subsequence(str1, str2):
    m = len(str1)
    n = len(str2)

    # Create a table to store lengths of the longest common subsequence
    # for each possible prefix of str1 and suffix of str2.
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Build the dp table in bottom-up manner.
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1] and (i == 1 or dp[i - 2][j - 1] > dp[i - 1]):
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Backtrack and construct the LCS.
    i, j = m, n
    while i > 0 and j > 0:
        if str1[i - 1] == str2[j - 1]:
            i -= 1
            j -= 1
            dp[i][j] = dp[i - 1][j - 1] + 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    # Reconstruct the LCS from the dp table.
    lcs = ""
    while i > 0:
        lcs = str1[i - 1] + lcs
        i -= 1

    return lcs


