    def find_nth_from_beginning(self, n):
        current = self.head
        for i in range(n):
            current = current.next
        return current.data

    def find_nth_from_end(self, n):
        current = self.tail
        for i in range(n):
            current = current.prev
        return current.data

    def reverse_order(self):
        current = self.head
        while current:
            next_node = current.next
            current.next = current.prev
            current.prev = next_node
            current = next_node
