import datetime

def convert_time_zones(input_file):
    # Step 1: Read the input text file
    with open(input_file, 'r') as f:
        data = f.read()

    # Step 2: Parse the time zone data from the input file
    time_zones = []
    for line in data.split('\n'):
        if line.startswith('UTC'):
            offset = int(line.split(':')[1].strip())
            time_zones.append((offset, line.split(':')[2].strip()))

    # Step 3: Convert the time zone data into a dictionary where the key is the UTC offset and the value is a list of time zones
    time_zone_dict = {}
    for offset, time_zone in time_zones:
        if offset in time_zone_dict:
            time_zone_dict[offset].append(time_zone)
        else:
            time_zone_dict[offset] = [time_zone]

    # Step 4: Convert the time zone data into a dictionary where the key is the time zone and the value is the UTC offset
    time_zone_offset_dict = {}
    for offset, time_zones in time_zone_dict.items():
        for time_zone in time_zones:
            if time_zone in time_zone_offset_dict:
                time_zone_offset_dict[time_zone].append(offset)
            else:
                time_zone_offset_dict[time_zone] = [offset]

    # Step 5: Convert the time zone data into a dictionary where the key is the time zone and the value is the time zone in the user's local time
    user_time_zone = datetime.datetime.now().strftime('%Z')
    user_offset = datetime.datetime.now().utcoffset().total_seconds() / 3600
    user_time_zone_dict = {user_time_zone: user_offset}

    # Step 6: Print the converted time zones
    for time_zone, offsets in time_zone_offset_dict.items():
        if user_time_zone in offsets:
            print(f"{time_zone} ({offsets[0]} hours UTC) is the same as {user_time_zone} ({user_offset} hours UTC)")
        else:
            print(f"{time_zone} ({offsets[0]} hours UTC) is not the same as {user_time_zone} ({user_offset} hours UTC)")

if __name__ == "__main__":
    input_file = "time_zones.txt"
    convert_time_zones(input_file)
