import urllib.parse
import urllib.request
import html.parser


class LinkParser(html.parser.HTMLParser):
    def __init__(self, keyword):
        super().__init__()
        self.keyword = keyword
        self.links = set()

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            for attr in attrs:
                if attr[0] == 'href':
                    url = attr[1]
                    if self.keyword in url:
                        absolute_url = urllib.parse.urljoin(self.base_url, url)
                        self.links.add(absolute_url)

    def parse(self, url):
        self.base_url = url
        try:
            response = urllib.request.urlopen(url)
            html_data = response.read().decode('utf-8')
            self.feed(html_data)
        except Exception as e:
            print(f"Error parsing URL: {url}")
            print(e)


def sort_links(links):
    return sorted(links, key=lambda link: link.lower())


def scrape_webpage(url, keyword):
    parser = LinkParser(keyword)
    parser.parse(url)
    sorted_links = sort_links(parser.links)
    for link in sorted_links:
