        if k <= 0 or k > len(self.heap):
            raise IndexError("k is out of range")

        heap_copy = MinHeap()
        heap_copy.heap = self.heap[:]
        heap_copy.indices = self.indices.copy()

        kth_smallest = None

        for _ in range(k):
            kth_smallest = heap_copy.delete()

