```python
def largest_prime_factor(n):
    if n < 2:
        return 1
    sieve = [True] * (n // 2 + 1)
    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n, i):
                sieve[j] = False
    primes = [p for p in range(2, n) if sieve[p]]
    return max(primes)

