class Triangle:
    def __init__(self, a, b, c):
        self.a = a
        self.b = b
        self.c = c

    def area(self):
        # Heron's formula for the area of a triangle with sides a, b, and c
        s = (self.a + self.b + self.c) / 2
        return s * (s - self.a) * (s - self.b) * (s - self.c)

    def perimeter(self):
        return self.a + self.b + self.c

    def is_equilateral(self):
        return all([self.a == self.b == self.c])

    def is_isosceles(self):
        return any([self.a == self.b or self.a == self.c or self.b == self.c])

    def is_scalene(self):
        return not self.is_equilateral() and not self.is_isosceles()

    def __str__(self):
        return f"Triangle(a={self.a}, b={self.b}, c={self.c})"


# Example usage:
triangle = Triangle(3, 4, 5)
print(triangle)  # Output: Triangle(a=3, b=4, c=5)
print(triangle.area())  # Output: 12
print(triangle.perimeter())  # Output: 12
print(triangle.is_equilateral())  # Output: False
print(triangle.is_isosceles())  # Output: True
print(triangle.is_scalene())  # Output: False

