    def __init__(self, value=0):
        self.value = value
        self.precision = 10

    def __repr__(self):
        return str(self.value)

    def __add__(self, other):
        return CustomNumber(self.value + other.value)

    def __sub__(self, other):
        return CustomNumber(self.value - other.value)

    def __mul__(self, other):
        return CustomNumber(self.value * other.value)

    def __truediv__(self, other):
        return CustomNumber(self.value / other.value)

def natural_log(x, iterations=100):
    if x <= 0:
        raise ValueError("The natural logarithm is undefined for non-positive numbers.")

    result = CustomNumber(x - 1)
    numerator = CustomNumber(result)
    denominator = CustomNumber(1)
    precision = CustomNumber(1)

