        self.data = data
        self.next = None

class Stack:
    def __init__(self):
        self.head = None
        self.min_value = None

    def push(self, item):
        new_node = Node(item)
        new_node.next = self.head
        self.head = new_node
        if self.min_value is None or item < self.min_value:
            self.min_value = item

    def pop(self):
        if self.is_empty():
            return None
        popped = self.head.data
        self.head = self.head.next
        if popped == self.min_value:
            self._update_min_value()
        return popped

    def peek(self):
        if self.is_empty():
            return None
        return self.head.data

    def is_empty(self):
        return self.head is None

    def size(self):
        count = 0
        current = self.head
        while current:
            count += 1
            current = current.next
        return count

    def get_min(self):
        if self.is_empty():
            return None
        return self.min_value

    def sort(self):
