To expand the functionality of the Python class to support multiple data types, we can define a new class called `MultiContainer` that inherits from the `Container` class. The `MultiContainer` class will have a `data_types` attribute that will store a list of the supported data types.

Here's an example implementation of the `MultiContainer` class:

```python
class Container:
    def __init__(self, data):
        self.data = data

    def add_data(self, data):
        self.data.append(data)

    def remove_data(self, data):
        self.data.remove(data)

    def search(self, data):
        return data in self.data

class MultiContainer(Container):
    def __init__(self, data_types=[]):
        super().__init__(data_types)
        self.data_types = data_types

    def add_data_type(self, data_type):
        self.data_types.append(data_type)

    def remove_data_type(self, data_type):
        self.data_types.remove(data_type)

    def search_data_type(self, data_type, criteria):
        if data_type in self.data_types:
            if criteria == 'length':
                return [data for data in self.data if isinstance(data, data_type) and len(data) == criteria]
            elif criteria == 'value':
                return [data for data in self.data if isinstance(data, data_type) and data == criteria]
            else:
                return [data for data in self.data if isinstance(data, data_type)]
        else:
            return []

    def sort_data(self, property, order):
        if property == 'alphabetical':
            self.data.sort(key=lambda x: x if isinstance(x, str) else x[0])
        elif property == 'numerical':
            if order == 'ascending':
                self.data.sort(key=lambda x: x if isinstance(x, int) else x[0])
            else:
                self.data.sort(key=lambda x: x if isinstance(x, int) else x[0], reverse=True)
        else:
            raise ValueError('Invalid property specified')
```

