class Queue:
    def __init__(self):
        self.queue = []
        self.id_counter = 0

    def enqueue(self, element):
        self.queue.append(element)
        self.id_counter += 1
        return self.id_counter - 1

    def dequeue(self):
        if not self.queue:
            raise IndexError("Cannot dequeue from an empty queue")
        element = self.queue.pop(0)
        self.log_to_queue_log("Dequeued", element)
        return element

    def get_front(self):
        if not self.queue:
            raise IndexError("Cannot get front element from an empty queue")
        return self.queue[0]

    def is_empty(self):
        return len(self.queue) == 0

    def size(self):
        return len(self.queue)

    def clear(self):
