def weighted_median(data, weights, threshold):
    n = len(data)
    if n % 2 == 0:
        return (data[n // 2 - 1] + data[n // 2]) / 2
    else:
        return data[n // 2]

    # Check if the sum of weights of numbers less than or equal to the median is greater than or equal to the threshold
    sum_weights_less_than_median = 0
    for i in range(n):
