```python
def bubble_sort(arr, reverse=False):
    n = len(arr)

    for i in range(n):
        for j in range(0, n - i - 1):
            if reverse:
                if arr[j] > arr[j + 1]:
                    arr[j], arr[j + 1] = arr[j + 1], arr[j]
            else:
                if arr[j] > arr[j + 1]:
                    arr[j], arr[j + 1] = arr[j + 1], arr[j]

    return arr


