def calculate_equation(equation):
    # Split the equation into a list of tokens
    tokens = equation.split()

    # Define operator precedence
    precedence = {'*': 1, '/': 1, '%': 1, '+': 2, '-': 2}

    # Initialize the stack and output list
    stack = []
    output = []

    # Iterate through the tokens
    for token in tokens:
        if token.isdigit():
            # If the token is a number, add it to the output list
            output.append(token)
        elif token in precedence:
            # If the token is an operator, pop operators from the stack
            # and add them to the output list until the stack is empty
            # or the top operator has lower precedence
            while stack and stack[-1] in precedence and precedence[stack[-1]] <= precedence[token]:
                output.append(stack.pop())
            stack.append(token)
        elif token == '(':
            # If the token is a left parenthesis, push it onto the stack
            stack.append(token)
        elif token == ')':
            # If the token is a right parenthesis, pop operators from the stack
            # and add them to the output list until a left parenthesis is found
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            if stack and stack[-1] == '(':
                stack.pop()

    # Pop any remaining operators from the stack and add them to the output list
    while stack:
        output.append(stack.pop())

    # Evaluate the postfix expression
    stack = []
    for token in output:
        if token.isdigit():
            stack.append(int(token))
        elif token in precedence:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a / b)
            elif token == '%':
                stack.append(a % b)

    # The final result is the only element left on the stack
    return stack[0]
