Here is an implementation of a doubly linked list in Python:

```python
class Node:
    def __init__(self, data):
        self.data = data
        self.prev = None
        self.next = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None

    def insert_at_beginning(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
            self.tail = new_node
        else:
            new_node.next = self.head
            self.head.prev = new_node
            self.head = new_node

    def insert_at_end(self, data):
        new_node = Node(data)
        if self.tail is None:
            self.head = new_node
            self.tail = new_node
        else:
            new_node.prev = self.tail
            self.tail.next = new_node
            self.tail = new_node

    def delete_node(self, data):
        current = self.head
        while current:
            if current.data == data:
                if current.prev is None:
                    self.head = current.next
                    if self.head:
                        self.head.prev = None
                    else:
                        self.tail = None
                elif current.next is None:
                    self.tail = current.prev
                    if self.tail:
                        self.tail.next = None
                    else:
                        self.head = None
                else:
                    current.prev.next = current.next
                    current.next.prev = current.prev
                return
            current = current.next

    def length(self):
        current = self.head
        count = 0
        while current:
            count += 1
            current = current.next
        return count

    def traverse_forward(self):
        current = self.head
        while current:
            print(current.data, end=" ")
            current = current.next
        print()

    def traverse_backward(self):
        current = self.tail
        while current:
            print(current.data, end=" ")
            current = current.prev
        print()

# Example usage:
dll = DoublyLinkedList()
dll.insert_at_beginning(3)
dll.insert_at_beginning(2)
dll.insert_at_beginning(1)
dll.insert_at_end(4)
dll.insert_at_end(5)
dll.delete_node(3)
print("Length:", dll.length())
dll.traverse_forward()  # Output: 1 2 4 5
dll.traverse_backward() # Output: 5 4 2 1
```

This implementation uses two classes, `Node` and `DoublyLinkedList`. `Node` represents each node in the doubly linked list and `DoublyLinkedList` represents the entire list. The `Node` class has three attributes - `data` to store the data, `prev` to store the reference to the previous node, and `next` to store the reference to the next node.

The `DoublyLinkedList` class has two attributes - `head` to store the reference to the first node and `tail` to store the reference to the last node. The class has methods to perform the required operations - `insert_at_beginning` to insert a new node at the beginning of the list, `insert_at_end` to insert a new node at the end of the list, `delete_node` to delete a node from the list, `length` to find the length of the list, `traverse_forward` to traverse the list in the forward direction, and `traverse_backward` to traverse the list in the backward direction.

