    def get_author(self) -> str:
        return self.author

    def get_genre(self) -> str:
        return self.genre

    def get_publication_year(self) -> int:
        return self.publication_year

class Library:
    def __init__(self):
        self.books = []

    def add_book(self, book: Book) -> None:
        if book not in self.books:
            self.books.append(book)

    def remove_book(self, book: Book) -> None:
        if book in self.books:
            self.books.remove(book)

    def get_books_by_author(self, author: str) -> List[Book]:
        books_by_author = []
        for book in self.books:
            if book.get_author() == author:
                books_by_author.append(book)
        return books_by_author

    def get_books_by_genre(self, genre: str) -> List[Book]:
        books_by_genre = []
        for book in self.books:
            if book.get_genre() == genre:
                books_by_genre.append(book)
        return books_by_genre

    def get_books_published_after_year(self, year: int) -> List[Book]:
        books_published_after_year = []
        for book in self.books:
            if book.get_publication_year() > year:
                books_published_after_year.append(book)
        return books_published_after_year
